#include "resident/domains/tasks/task_source_projection.hpp"
// 只有显式选择才要求永久开工源；旧订单档不能被无来源升级为已证明的历史。
#include "task_shop_order_contact_profile.hpp"
#include "resident/domains/tasks/shop_orders/task_shop_order_boundary.hpp"
#include <set>
namespace hanmo::resident {
Outcome<bool> decode_task_shop_order_contact_profile(const BoundaryValue& scenario,const std::vector<StableId>& caps){try{using namespace boundary;std::set<StableId> keys;for(const auto& row:object(scenario,"scenario"))if(!keys.insert(row.first).second)fail("DuplicateTaskShopOrderContactProfileField",row.first);const auto* p=scenario.find("task_shop_order_contact_profile");if(!p)return {true,false,{}};if(string(*p,"task_shop_order_contact_profile")!="original_shop_order_contacts_v1")unsupported("UnsupportedTaskShopOrderContactProfile","task_shop_order_contact_profile");for(const auto* cap:{"task_shop_order_contacts_v1","task_shop_orders_v1","family_life_v1"})if(std::find(caps.begin(),caps.end(),cap)==caps.end())unsupported("TaskShopOrderContactCapabilityRequired",cap);auto original=decode_task_shop_order_profile(scenario,caps);if(!original.ok)return original;if(!original.value||!scenario.find("family_life"))unsupported("TaskShopOrderContactOriginalProfileRequired","task_shop_order_contact_profile");return {true,true,{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Outcome<Integer> task_shop_order_contact_selected_version(const std::vector<std::pair<StableId,StableId>>& modules){std::map<StableId,StableId> selected;const std::set<StableId> names{task_shop_order_contact_module,"task_shop_orders","private_shops","family_life"};for(const auto& row:modules)if(names.count(row.first)){if(!selected.emplace(row.first,row.second).second)return {false,{},common_failure("DuplicateTaskShopOrderContactModule",row.first).error};}auto own=selected.find(task_shop_order_contact_module);if(own==selected.end())return {true,0,{}};if(own->second!="1")return {false,{},common_failure("UnsupportedTaskShopOrderContactVersion").error};for(const auto* dependency:{"task_shop_orders","private_shops","family_life"}){auto at=selected.find(dependency);if(at==selected.end()||at->second!="1")return {false,{},common_failure("TaskShopOrderContactDependencyRequired",dependency).error};}return {true,1,{}};}
Status validate_task_shop_order_contact_layout(const CommonStore& c,const std::vector<std::pair<StableId,StableId>>& modules,bool selected,const TaskShopOrderContactState* s){auto version=task_shop_order_contact_selected_version(modules);if(!version.ok)return {false,{},version.error};if(version.value!=(selected?1:0)||selected!=bool(s)||(s&&s->version!=1))return common_failure("TaskShopOrderContactProfileMismatch");if(!selected)for(const auto& row:c.state().facts.rows())if(row.second.kind==task_shop_order_contact_started_kind||row.second.domain==task_shop_order_contact_module)return common_failure("TaskShopOrderContactProfileRequired",row.first);return common_success();}
Outcome<bool> emit_task_shop_order_contact_fact_payload_fields(ProjectionWriter& w,const TaskShopOrderContactState* state,const FactRecord& h){if(h.domain!=task_shop_order_contact_module&&h.kind!=task_shop_order_contact_started_kind)return {true,false,{}};if(!state||h.kind!=task_shop_order_contact_started_kind||h.domain!=task_shop_order_contact_module)return {false,{},common_failure("TaskShopOrderContactFactMismatch",h.id).error};auto status=emit_task_shop_order_contact_fact_fields(w,*state,h.id);if(!status.ok)return {false,{},status.error};w.field("kind",h.kind);w.field("domain",h.domain);return {w.status().ok,w.status().ok,w.status().error};}
Status emit_task_shop_order_contact_fact_payloads_fields(ProjectionWriter& w,const CommonStore& c,const TaskShopOrderContactState* state){std::size_t emitted=0;for(const auto& row:c.state().facts.rows()){const auto& h=row.second;if(h.domain!=task_shop_order_contact_module&&h.kind!=task_shop_order_contact_started_kind)continue;if(!state||h.id!=row.first||h.kind!=task_shop_order_contact_started_kind||h.domain!=task_shop_order_contact_module)return common_failure("TaskShopOrderContactFactMismatch",row.first);auto checked=w.object(row.first,[&](auto&out){auto status=emit_task_shop_order_contact_fact_fields(out,*state,row.first);if(!status.ok)return status;out.field("kind",h.kind);out.field("domain",h.domain);return out.status();});if(!checked.ok)return checked;++emitted;}if(state&&emitted!=state->starts.size())return common_failure("TaskShopOrderContactFactCoverageMismatch");return w.status();}
Outcome<BoundaryValue> task_shop_order_contact_fact_payloads(const CommonStore& c,const TaskShopOrderContactState* state){BoundaryValue value;BoundaryProjectionWriter writer(value);auto checked=writer.object("",[&](auto&out){return emit_task_shop_order_contact_fact_payloads_fields(out,c,state);});if(checked.ok)checked=writer.finish();return checked.ok?Outcome<BoundaryValue>{true,std::move(value),{}}:Outcome<BoundaryValue>{false,{},checked.error};}
Status validate_task_shop_order_contact_json_payloads(const CommonStore& c,const TaskShopOrderContactState* state,const BoundaryValue& value){try{using namespace boundary;auto expected=task_shop_order_contact_fact_payloads(c,state);if(!expected.ok)return {false,{},expected.error};for(const auto& row:object(expected.value,"task_shop_order_contacts/facts"))if(!compare_boundary(field(field(value,"facts","state"),row.first,"facts"),row.second).exact())return common_failure("TaskShopOrderContactFactPayloadMismatch",row.first);return common_success();}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
}
